 page=location.hash.slice(1)||'workspace';kind:Kind='数据库';activeResource=fixtures['数据库'][0];templateTab='监控项';selectedTemplate=templateFixtures[0];query='';filter='全部类型';dialog='';dialogText='';editName='';message='';secondary=true;override='90';testState='idle';testScenario='success';applied=false;sampleArrived=false;metricMode='图形';range='6h';ack=false;recovered=false;recoverySample='60.0';ackText='';ruleName='连接使用率过高';threshold='80';recovery='70';sample='95';exprResult='';advanced=false;savedRule=false;notice='';menuOpen=false;loading=false;customTemplates:typeof templateFixtures=[];editItemName='连接使用率';itemDraftName='';itemDraftKey='';itemDraftInterval='60';itemDraftUnit='%';itemSaved=false;extraItems:Record<string,string[]>={};extraDefinitions:Record<string,{key:string,unit:string}>={};

 workspaceView='home';workspaceEntryToken=0;eventTab='活动告警';platformTab='运行观测';platformScenario='enabled';platformAnalyzed=false;platformRecovered=false;relatedServer=true;bindQuery='';bindFilter='全部授权模板';bindingDraft:string[]=[];bindingVersions:Record<string,string>={};resourceBindings:Record<string,string[]>={'mysql-order-prod':['MySQL 生产基线@2.3.0','MySQL 复制增强@1.2.0'],'pg-analytics-01':['PostgreSQL 基线@1.6.0'],'redis-session-01':['Redis 基线@1.0.0'],'app-node-01':['Linux 主机基线@1.8.0'],'db-node-01':['Linux 主机基线@1.8.0'],'core-switch-01':['华为交换机 SNMP 基线@1.4.0']};
 allTemplates(){return [...templateFixtures,...this.customTemplates];}
 compatible(t:typeof templateFixtures[number]){if(t.kind!==this.kind)return '资源类别不匹配';const v=this.activeResource.version.toLowerCase();if(this.kind==='数据库'){const engine=t.engine;if(!v.includes(engine))return '数据库引擎不匹配';}if(this.kind==='网络设备'&&t.engine==='huawei'&&!v.includes('huawei'))return '设备厂商不匹配';return t.version.includes('draft')?'模板为草稿，尚未发布':'';}
 bindings(){const key=this.activeResource.name;if(!this.resourceBindings[key])this.resourceBindings[key]=[];return this.resourceBindings[key];}
 boundTemplates(){return this.bindings().map(b=>{const [name,version]=b.split('@');const t=this.allTemplates().find(t=>t.name===name);return t?{...t,version}:null;}).filter((t):t is typeof templateFixtures[number]=>t!==null);}
 invalidateConfig(){this.testState='idle';this.applied=false;this.sampleArrived=false;}
 openBindings(){this.bindingDraft=[...this.bindings()];this.bindingVersions=Object.fromEntries(this.allTemplates().map(t=>[t.name,this.bindingDraft.find(b=>b.startsWith(t.name+'@'))?.split('@')[1]||t.version]));this.bindQuery='';this.bindFilter='全部授权模板';this.dialog='bind';this.requestUpdate();}
 openWorkspace(view='home'){this.workspaceView=view;this.workspaceEntryToken++;if(view==='resource'){this.kind='数据库';this.activeResource=fixtures['数据库'][0];}this.go('workspace');}
 openEvents(tab='活动告警'){this.eventTab=tab;this.go('events');}
 resourceRoute(){return this.kind==='数据库'?'databases':this.kind==='服务器'?'servers':'network';}
 prototypeNav=(e:CustomEvent<{page:string;resource?:Resource;kind?:Kind;target?:string}>)=>{const d=e.detail;const match=d.resource||Object.values(fixtures).flat().find(r=>r.name===d.target);if(match){this.activeResource=match;this.kind=d.kind||((Object.entries(fixtures).find(([,rs])=>rs.includes(match))?.[0]||'数据库') as Kind);}if(d.page==='workspace-resource'){this.workspaceView='new';this.workspaceEntryToken++;this.go('workspace');}else if(d.page==='workspace'){this.openWorkspace();}else this.go(d.page);};
 resourceOverview(){return html`<slide-overview-v3 .resources=${fixtures} @prototype-nav=${this.prototypeNav}></slide-overview-v3>`;}
