 disconnectedCallback(){super.disconnectedCallback();window.removeEventListener('hashchange',this.onHash);}
 onHash=()=>{if(location.hash==='#main-content')return;if(this.page==='resource-overview')document.querySelector<OverviewV3>('slide-overview-v3')?.rememberScroll();window.scrollTo(0,0);this.page=location.hash.slice(1)||'workspace';if(this.page==='servers')this.kind='服务器';if(this.page==='network')this.kind='网络设备';if(this.page==='databases')this.kind='数据库';if(this.page==='resource-diagnosis')this.workspaceView='resource';if(this.page==='discovery'&&this.selectedTemplate.kind==='数据库')this.selectedTemplate=templateFixtures[1];this.query='';this.notice='';this.requestUpdate();};
