 go(page:string){if(this.page===page){this.requestUpdate();return;}location.hash=page;}
 icon(name:string){return html`<svg class="ico" viewBox="0 0 17 17" aria-hidden="true">${paths[name]||paths.templates}</svg>`;}
 badge(text:string){const variant=/正常|有效|已生效|已恢复|成功|已发布/.test(text)?'ok':/问题|失败|超时/.test(text)?'danger':/未|无法|不支持|等待|草稿|抑制/.test(text)?'warn':'info';return html`<app-badge variant=${variant}>${text}</app-badge>`;}
 btn(label:string,action:()=>void,primary=false){return html`<button class=${primary?'btn-primary':'btn'} @click=${action}>${label}</button>`;}
 table(columns:[string,string][],rows:Record<string,unknown>[],resource=false){return html`<div class="mobile-hint">左右滑动查看完整列和操作 →</div><app-card compact><div class="table-scroll ${resource?'resource-table':''}"><app-data-table .columns=${columns.map(([key,label])=>({key,label}))} .rows=${rows} .striped=${false} emptyMessage="没有匹配的数据，请调整筛选条件"></app-data-table></div><div class="table-footer"><span>共 ${rows.length} 条${this.query?'匹配记录':''}</span><span>第 1 页 · 全部展示</span></div></app-card>`;}
 tabs(labels:string[],selected:string,fn:(v:string)=>void,counts?:number[]){return html`<div class="tabs" role="tablist">${labels.map((t,i)=>html`<button class="tab ${selected===t?'active':''}" role="tab" aria-selected=${selected===t} @click=${()=>fn(t)}>${t}${counts?html`<span class="count">${counts[i]}</span>`:nothing}</button>`)}</div>`;}
 heading(title:string,sub:string,actions:unknown=nothing,eyebrow=''){return html`<div class="heading"><div>${eyebrow?html`<div class="eyebrow">${eyebrow}</div>`:nothing}<h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
