 context(){const t=this.boundTemplates()[0];return {template:t?.name||'未关联模板',version:t?.version||'—',metric:this.kind==='服务器'?'CPU 使用率':this.kind==='网络设备'?'端口利用率':'连接使用率',key:this.kind==='服务器'?'linux.cpu.util.pct':this.kind==='网络设备'?'network.interface.util.pct':'mysql.connections.usage',items:t?.items||0,triggers:t?.triggers||0};}
